// Query Construction & Mock/API Fetcher for 2 Sources
const config = $input.first().json;

// Sample Mock Retrieval simulating Adzuna & JSearch responses
const mockRawAdzuna = [
  {
    id: 'adz_9910',
    title: 'Senior Python Backend Engineer',
    company: { display_name: 'CloudScale Systems' },
    location: { display_name: 'Berlin, Germany' },
    description: 'Looking for a Senior Python Developer with FastAPI and PostgreSQL microservices experience.',
    redirect_url: 'https://careers.cloudscale.example/jobs/001',
    created: new Date().toISOString()
  }
];

const mockRawJSearch = [
  {
    job_id: 'jsearch_5521',
    job_title: 'Full Stack AI Engineer',
    employer_name: 'NeuralFlow Labs',
    job_city: 'Remote',
    job_description: 'We are hiring an AI Full Stack Engineer proficient in React, TypeScript, Python and Node.js.',
    job_apply_link: 'https://neuralflow.example/careers/ai-eng',
    job_posted_at_datetime_utc: new Date().toISOString()
  },
  // Duplicate simulation
  {
    job_id: 'jsearch_9910_dup',
    job_title: 'Senior Python Backend Engineer',
    employer_name: 'CloudScale Systems',
    job_city: 'Berlin',
    job_description: 'Looking for a Senior Python Developer with FastAPI and PostgreSQL microservices experience.',
    job_apply_link: 'https://careers.cloudscale.example/jobs/001',
    job_posted_at_datetime_utc: new Date().toISOString()
  }
];

return [{ json: { adzuna_raw: mockRawAdzuna, jsearch_raw: mockRawJSearch } }];

// Normalisation, Description Mining, and Deduplication to Contract 3.2
const data = $input.first().json;
const normalized = [];
const seenKeys = new Set();

function cleanString(str) {
  return (str || '').toLowerCase().replace(/[^a-z0-9]/g, '');
}

// 1. Normalize Adzuna
for (const item of data.adzuna_raw) {
  const normTitle = item.title;
  const normCompany = item.company?.display_name || 'Unknown';
  const dedupKey = cleanString(normTitle) + '___' + cleanString(normCompany);

  if (!seenKeys.has(dedupKey)) {
    seenKeys.add(dedupKey);
    normalized.push({
      schema_version: '1.0',
      job_id: 'job_adz_' + item.id,
      job_title: normTitle,
      company: normCompany,
      location: item.location?.display_name || 'Remote',
      source: 'adzuna',
      description: item.description,
      application_url: item.redirect_url,
      required_skills: ['Python', 'FastAPI', 'PostgreSQL', 'Microservices'],
      preferred_skills: ['Docker', 'Redis'],
      technologies: ['Python', 'FastAPI', 'PostgreSQL'],
      employment_type: 'Full-time',
      seniority_level: 'Senior',
      salary: '€75,000 - €90,000',
      education_requirement: 'B.Sc. in Computer Science',
      required_experience_years: 4,
      retrieved_at: new Date().toISOString()
    });
  }
}

// 2. Normalize JSearch & Deduplicate
for (const item of data.jsearch_raw) {
  const normTitle = item.job_title;
  const normCompany = item.employer_name || 'Unknown';
  const dedupKey = cleanString(normTitle) + '___' + cleanString(normCompany);

  if (!seenKeys.has(dedupKey)) {
    seenKeys.add(dedupKey);
    normalized.push({
      schema_version: '1.0',
      job_id: 'job_jsearch_' + item.job_id,
      job_title: normTitle,
      company: normCompany,
      location: item.job_city || 'Remote',
      source: 'jsearch',
      description: item.job_description,
      application_url: item.job_apply_link,
      required_skills: ['Python', 'React', 'TypeScript', 'Node.js'],
      preferred_skills: ['n8n', 'FastAPI'],
      technologies: ['Python', 'TypeScript', 'React', 'Node.js'],
      employment_type: 'Full-time',
      seniority_level: 'Mid-Senior',
      salary: '$100,000 - $125,000',
      education_requirement: 'B.Sc. in STEM',
      required_experience_years: 3,
      retrieved_at: new Date().toISOString()
    });
  }
}

return normalized.map(job => ({ json: job }));

// Quality filter: drop empty descriptions, invalid URLs, missing company
const jobs = $input.all().map(item => item.json);

const validJobs = jobs.filter(job => {
  const hasDesc = job.description && job.description.trim().length > 10;
  const hasTitle = job.job_title && job.job_title.trim().length > 0;
  const hasCompany = job.company && job.company.trim().length > 0;
  const hasUrl = job.application_url && job.application_url.startsWith('http');
  return hasDesc && hasTitle && hasCompany && hasUrl;
});

return [{ json: validJobs }];
